lb_a_sema_prelude_Prelude_arr19 lb_sema_prelude_modules = ((lb_a_sema_prelude_Prelude_arr19){{((lb_sema_prelude_Prelude){.name = ((lb_str){"platform", 8}), .text = ((lb_str){"## The target of the build, as constants (\302\24719.5): generated by the compiler from\n## `--target` (`Target.module_text`); this placeholder is what the prelude embeds and the\n## checker replaces. `os` re-exports these for programs; the standard library branches\n## on them directly.\npub let name: str = \"arm64-macos\"\npub let macos: bool = true\npub let linux: bool = false\npub let windows: bool = false\npub let posix: bool = true\npub let arm64: bool = true\npub let x86_64: bool = false\npub let pointer_bits: u32 = 64\n", 513})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"core", 4}), .text = ((lb_str){"import c\nextern func write(descriptor: i32, buffer: const void*, count: usize) -> isize\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func malloc(size: usize) -> void*?\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memcmp(a: const void*, b: const void*, count: usize) -> i32\nextern func strlen(text: c.str) -> usize\nextern func snprintf(buffer: void*, size: usize, format: c.str, ...) -> i32\n\n## Stop the program with its reason on stderr (\302\2478.7).\npub func trap(message: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)message, strlen(message)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## `trap: message: detail`, for an `assert` whose message is computed (\302\24711.6).\npub func trap_two(message: c.str, detail: c.str) -> never:\n    let prefix = \"trap: \"\n    discard(write(2, prefix.bytes.data, prefix.length))\n    discard(write(2, (const void*)message, strlen(message)))\n    let sep = \": \"\n    discard(write(2, sep.bytes.data, 2))\n    discard(write(2, (const void*)detail, strlen(detail)))\n    let newline = \"\\n\"\n    discard(write(2, newline.bytes.data, 1))\n    c_exit(1)\n\n## The buffer `format` and f\"...\" fill: the bytes, their capacity, and the count used.\npub struct FormatBuffer:\n    pub var data: u8*\n    pub var capacity: usize\n    pub var used: usize\n\n## Append `count` bytes; 1 when they do not fit, and the buffer is then over capacity.\npub func format_put(b: FormatBuffer*, text: const void*?, count: usize) -> i32:\n    if count > b.capacity or b.used > b.capacity - count:\n        b.used = b.capacity +% 1\n        return 1\n    if let source = text:\n        if count > 0:\n            discard(memcpy(&b.data[b.used], source, count))\n    b.used += count\n    return 0\n\npub func format_u64(b: FormatBuffer*, value: u64) -> i32:\n    var digits: u8[24] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[23] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        digits[24 - n] = (u8)(48 + v % 10)\n        v = v // 10\n    return format_put(b, &digits[24 - n], n)\n\npub func format_i64(b: FormatBuffer*, value: i64) -> i32:\n    if value < 0:\n        let minus = \"-\"\n        if format_put(b, minus.bytes.data, 1) != 0:\n            return 1\n        return format_u64(b, 0 -% (u64)value)\n    return format_u64(b, (u64)value)\n\n## `%g`, as the C library spells it, so both backends print one text.\npub func format_f64(b: FormatBuffer*, value: f64) -> i32:\n    var text: u8[64] = ---\n    let n = snprintf((void*)&text[0], 64, \"%g\", value)\n    if n < 0:\n        return 1\n    return format_put(b, &text[0], (usize)n)\n\npub func format_bool(b: FormatBuffer*, value: bool) -> i32:\n    let word = \"true\" if value else \"false\"\n    return format_put(b, word.bytes.data, word.length)\n\n## A `char` displays as itself, in UTF-8 (\302\24714.4).\npub func format_char(b: FormatBuffer*, value: char) -> i32:\n    let cp = u32(value)\n    var out: u8[4]\n    var n: usize = 0\n    if cp < 0x80:\n        out[0] = u8(cp)\n        n = 1\n    elif cp < 0x800:\n        out[0] = u8(0xC0 | (cp >> 6))\n        out[1] = u8(0x80 | (cp & 0x3F))\n        n = 2\n    elif cp < 0x10000:\n        out[0] = u8(0xE0 | (cp >> 12))\n        out[1] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[2] = u8(0x80 | (cp & 0x3F))\n        n = 3\n    else:\n        out[0] = u8(0xF0 | (cp >> 18))\n        out[1] = u8(0x80 | ((cp >> 12) & 0x3F))\n        out[2] = u8(0x80 | ((cp >> 6) & 0x3F))\n        out[3] = u8(0x80 | (cp & 0x3F))\n        n = 4\n    return format_put(b, (const void*)&out, n)\n\n## The text so far, NUL-terminated when there is room.\npub func format_finish(b: FormatBuffer*) -> str:\n    if b.used < b.capacity:\n        b.data[b.used] = 0\n    if b.used > b.capacity:\n        return \"\"\n    return (str)u8[](b.data, b.used)\n\n## `hex`, `bin`, and `pad` return text in one of four rotating thread-local slots.\nlocal var show_bytes: u8[1024]\nlocal var show_next: u32\n\nfunc show_take(source: const u8*, count: usize) -> str:\n    let slot = (usize)(show_next & 3) * 256\n    show_next = show_next +% 1\n    var n = count\n    if n > 255:\n        n = 255\n    if n > 0:\n        discard(memcpy(&show_bytes[slot], source, n))\n    show_bytes[slot + n] = 0\n    return (str)show_bytes[slot..<slot + n]\n\npub func show_hex(value: u64) -> str:\n    var digits: u8[16] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[15] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        let d = (u8)(v & 15)\n        digits[16 - n] = d + 48 if d < 10 else d + 87\n        v = v >> 4\n    return show_take(&digits[16 - n], n)\n\npub func show_bin(value: u64) -> str:\n    var digits: u8[64] = ---\n    var n: usize = 0\n    var v = value\n    if v == 0:\n        digits[63] = 48\n        n = 1\n    while v != 0:\n        n += 1\n        digits[64 - n] = 48 + (u8)(v & 1)\n        v = v >> 1\n    return show_take(&digits[64 - n], n)\n\npub func show_pad(inner: str, width: usize) -> str:\n    var n = inner.length\n    if n >= width:\n        return show_take(inner.bytes.data, n)\n    var text: u8[256] = ---\n    var pad = width - n\n    if width > 255:\n        if n > 255:\n            n = 255\n        pad = 255 - n\n    for i in 0..<pad:\n        text[i] = 32\n    if n > 0:\n        discard(memcpy(&text[pad], inner.bytes.data, n))\n    return show_take(&text[0], pad + n)\n\n## The startup shim's pieces: the argument vector as `str[]` (checked) or `c.str[]`.\npub func arguments(count: i32, vector: c.str*) -> str[]:\n    let n = (usize)count\n    let block = malloc((n if n > 0 else 1) * sizeof(str)) else trap(\"memory.exhausted\")\n    let items = (str*)block\n    var i: usize = 0\n    while i < n:\n        let text = (str)vector[i]\n        if not utf8_ok(text.bytes.data, text.length):\n            trap(\"invalid_utf8\")\n        items[i] = text\n        i += 1\n    return str[](items, n)\n\npub func raw_arguments(count: i32, vector: c.str*) -> c.str[]:\n    return c.str[](vector, (usize)count)\n\n## A failed `main`: its error on stderr, exit status 1.\npub func main_failed(code: i32, message: str) -> i32:\n    var bytes: u8[1024] = ---\n    let line = format(bytes, f\"error {code}: {message}\\n\") catch:\n        return 1\n    discard(write(2, line.bytes.data, line.length))\n    return 1\n\n## The test runner's report line and its summary.\npub func test_report(name: str, failed: bool, message: str):\n    var bytes: u8[1024] = ---\n    let line = format(bytes, f\"FAIL  {name}\\n      error: {message}\\n\" if failed else f\"ok    {name}\\n\") catch:\n        return\n    discard(write(1, line.bytes.data, line.length))\n\npub func test_summary(total: i32, failed: i32) -> i32:\n    var bytes: u8[64] = ---\n    let line = format(bytes, f\"{total - failed} passed\\n\") catch:\n        return 1\n    discard(write(1, line.bytes.data, line.length))\n    return 0 if failed == 0 else 1\n\n## `print`: the text and a newline on stdout; `answer()` programs print their number.\npub func print_str(text: str):\n    discard(write(1, text.bytes.data, text.length))\n    let newline = \"\\n\"\n    discard(write(1, newline.bytes.data, 1))\n\npub func print_i64(value: i64):\n    var bytes: u8[32] = ---\n    let all: u8[] = bytes\n    var b = FormatBuffer(data = all.data, capacity = 32, used = 0)\n    discard(format_i64(&b, value))\n    discard(write(1, all.data, b.used))\n    let newline = \"\\n\"\n    discard(write(1, newline.bytes.data, 1))\n\n## Ordering of text: bytewise, then by length (\302\2477.4).\npub func str_compare(a: str, b: str) -> i32:\n    let n = a.length if a.length < b.length else b.length\n    var order: i32 = 0\n    if n > 0:\n        order = memcmp(a.bytes.data, b.bytes.data, n)\n    if order != 0:\n        return -1 if order < 0 else 1\n    if a.length < b.length:\n        return -1\n    return 1 if a.length > b.length else 0\n\n## The scalar starting at byte `index` of `count` bytes of valid UTF-8, its width left in\n## `width`: what `for character in text` steps by (\302\2475.5).\npub func utf8_scalar(text: const u8*, count: usize, index: usize, width: usize*) -> char:\n    let byte = text[index]\n    var w: usize = 1\n    var cp: u32 = (u32)byte\n    if byte >= 240:\n        w = 4\n        cp = (u32)(byte & 7)\n    elif byte >= 224:\n        w = 3\n        cp = (u32)(byte & 15)\n    elif byte >= 192:\n        w = 2\n        cp = (u32)(byte & 31)\n    if index + w > count:\n        w = count - index\n    var k: usize = 1\n    while k < w:\n        cp = (cp << 6) | (u32)(text[index + k] & 63)\n        k += 1\n    *width = w\n    return char(cp)\n\n## Whether `count` bytes are well-formed UTF-8: no overlong forms, no surrogates, nothing past U+10FFFF.\npub func utf8_ok(text: const u8*?, count: usize) -> bool:\n    let s = text else return count == 0\n    var i: usize = 0\n    while i < count:\n        let byte = s[i]\n        var w: usize = 1\n        var cp: u32 = 0\n        if byte < 128:\n            cp = (u32)byte\n        elif (byte & 224) == 192:\n            w = 2\n            cp = (u32)(byte & 31)\n        elif (byte & 240) == 224:\n            w = 3\n            cp = (u32)(byte & 15)\n        elif (byte & 248) == 240:\n            w = 4\n            cp = (u32)(byte & 7)\n        else:\n            return false\n        if i + w > count:\n            return false\n        var k: usize = 1\n        while k < w:\n            let x = s[i + k]\n            if (x & 192) != 128:\n                return false\n            cp = (cp << 6) | (u32)(x & 63)\n            k += 1\n        if w == 2 and cp < 128:\n            return false\n        if w == 3 and cp < 2048:\n            return false\n        if w == 4 and cp < 65536:\n            return false\n        if cp >= 55296 and cp <= 57343:\n            return false\n        if cp > 1114111:\n            return false\n        i += w\n    return true\n\n## `hash`: a per-process seed and a multiplicative mixer (\302\2477.4).\nvar hash_seed_value: u64\nvar hash_seeded: bool\n\npub func hash_seed() -> u64:\n    if not hash_seeded:\n        hash_seed_value = 11400714819323198485 ^ (u64)(usize)&hash_seed_value\n        hash_seeded = true\n    return hash_seed_value\n\npub func hash_mix(h: u64, x: u64) -> u64:\n    var r = h ^ x\n    r = r *% 11400714819323198485\n    r = r ^ (r >> 32)\n    return r\n\npub func hash_bytes(h: u64, data: const void*?, count: usize) -> u64:\n    var r = h\n    if let p = data:\n        let bytes = (const u8*)p\n        var i: usize = 0\n        while i < count:\n            r = hash_mix(r, (u64)bytes[i])\n            i += 1\n    return hash_mix(r, (u64)count)\n\n## Integer conversions between widths: `bits` of `value` as a 64-bit word.\nfunc mask_of(bits: i32) -> u64:\n    if bits >= 64:\n        return 18446744073709551615\n    return (1 << (u64)bits) - 1\n\nfunc sign_extend(value: i64, bits: i32) -> i64:\n    if bits >= 64:\n        return value\n    let m = mask_of(bits)\n    let x = (u64)value & m\n    if (x & (1 << (u64)(bits - 1))) != 0:\n        return (i64)(x | ~m)\n    return (i64)x\n\nfunc zero_extend(value: u64, bits: i32) -> u64:\n    return value & mask_of(bits)\n\nfunc signed_min(bits: i32) -> i64:\n    if bits >= 64:\n        return -9223372036854775807 - 1\n    return 0 -% (1 << (i64)(bits - 1))\n\nfunc signed_max(bits: i32) -> i64:\n    if bits >= 64:\n        return 9223372036854775807\n    return (1 << (i64)(bits - 1)) - 1\n\nfunc fits_signed(value: i64, bits: i32) -> bool:\n    return value >= signed_min(bits) and value <= signed_max(bits)\n\nfunc fits_unsigned(value: u64, bits: i32) -> bool:\n    return value <= mask_of(bits)\n\n## `T(x)` between integers (`mode` 0, checked) and `(T)x` (`mode` 1, truncating).\npub func conv_s(value: i64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32) -> i64:\n    var a = value\n    if from_signed != 0:\n        a = sign_extend(a, from_bits)\n    else:\n        a = (i64)zero_extend((u64)a, from_bits)\n    if mode == 0:\n        if to_signed != 0:\n            if not fits_signed(a, to_bits):\n                trap(\"integer conversion out of range\")\n            return a\n        if a < 0 or not fits_unsigned((u64)a, to_bits):\n            trap(\"integer conversion out of range\")\n        return a\n    let bits = (u64)a & mask_of(to_bits)\n    if to_signed != 0:\n        return sign_extend((i64)bits, to_bits)\n    return (i64)bits\n\npub func conv_u(value: u64, from_bits: i32, from_signed: i32, to_bits: i32, to_signed: i32, mode: i32) -> u64:\n    let s = sign_extend((i64)value, from_bits) if from_signed != 0 else (i64)zero_extend(value, from_bits)\n    if mode == 0:\n        if to_signed != 0:\n            if not fits_signed(s, to_bits):\n                trap(\"integer conversion out of range\")\n            return (u64)s\n        if s < 0 or not fits_unsigned((u64)s, to_bits):\n            trap(\"integer conversion out of range\")\n        return (u64)s\n    return zero_extend((u64)s, to_bits)\n\nfunc is_finite(value: f64) -> bool:\n    return value - value == 0.0\n\n## Float to integer: checked (`mode` 0) or saturating (`mode` 1); the cast inside is the target's own.\npub func f_to_s(value: f64, bits: i32, mode: i32) -> i64:\n    let low = (f64)signed_min(bits)\n    let high = (f64)signed_max(bits)\n    if mode == 0:\n        if not is_finite(value) or value < low or value > high:\n            trap(\"integer conversion out of range\")\n        return (i64)value\n    if value != value:\n        return 0\n    if value <= low:\n        return signed_min(bits)\n    if value >= high:\n        return signed_max(bits)\n    return (i64)value\n\npub func f_to_u(value: f64, bits: i32, mode: i32) -> u64:\n    let high = (f64)mask_of(bits)\n    if mode == 0:\n        if not is_finite(value) or value < 0.0 or value > high:\n            trap(\"integer conversion out of range\")\n        return (u64)value\n    if value != value or value < 0.0:\n        return 0\n    if value >= high:\n        return mask_of(bits)\n    return (u64)value\n\n## Saturating arithmetic (`+|`, `-|`, `*|`) on `bits`-wide operands in 64-bit words.\nfunc add_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ r) & (b ^ r)) < 0\n\nfunc sub_overflows_s(a: i64, b: i64, r: i64) -> bool:\n    return ((a ^ b) & (a ^ r)) < 0\n\nfunc mul_overflows_s(a: i64, b: i64) -> bool:\n    if a == 0 or b == 0:\n        return false\n    if a == -1:\n        return b == signed_min(64)\n    if b == -1:\n        return a == signed_min(64)\n    return (a *% b) // b != a\n\npub func adds_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\npub func adds_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return mask_of(bits)\n    return r\n\npub func subs_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return signed_min(bits) if a < 0 else signed_max(bits)\n    return r\n\npub func subs_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return 0\n    return a - b\n\npub func muls_s(x: i64, y: i64, bits: i32) -> i64:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return signed_min(bits) if (a < 0) != (b < 0) else signed_max(bits)\n    return a *% b\n\npub func muls_u(x: u64, y: u64, bits: i32) -> u64:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return mask_of(bits)\n    return zero_extend(a *% b, bits)\n\n## Checked-to-optional arithmetic (`+?`, `-?`, `*?`): the result through `out`, whether it fit.\npub func qadd_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a +% b\n    if add_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qadd_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    let r = a +% b\n    if r < a or not fits_unsigned(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qsub_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    let r = a -% b\n    if sub_overflows_s(a, b, r) or not fits_signed(r, bits):\n        return false\n    *out = r\n    return true\n\npub func qsub_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if a < b:\n        return false\n    *out = a - b\n    return true\n\npub func qmul_s(x: i64, y: i64, bits: i32, out: i64*) -> bool:\n    let a = sign_extend(x, bits)\n    let b = sign_extend(y, bits)\n    if mul_overflows_s(a, b) or not fits_signed(a *% b, bits):\n        return false\n    *out = a *% b\n    return true\n\npub func qmul_u(x: u64, y: u64, bits: i32, out: u64*) -> bool:\n    let a = zero_extend(x, bits)\n    let b = zero_extend(y, bits)\n    if b != 0 and a > mask_of(bits) // b:\n        return false\n    *out = a *% b\n    return true\n", 17228})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"memory", 6}), .text = ((lb_str){"import platform\n\nextern func malloc(size: usize) -> void*?\nextern func c_free as \"free\"(block: void*)\nextern func posix_memalign(memptr: void*?*, alignment: usize, size: usize) -> i32\nextern func memcpy(target: void*, source: const void*, count: usize) -> void*\nextern func memmove(target: void*, source: const void*, count: usize) -> void*\nextern func memset(target: void*, value: i32, count: usize) -> void*\n\n## What every allocator offers: blocks of bytes at an alignment, optionally\n## resized in place, and given back (\302\24712.4).\npub interface Allocator:\n    mutating func allocate(size: usize, alignment: usize) -> u8[]?\n    mutating func resize(block: u8[], size: usize) -> bool\n    mutating func release(block: u8[])\n\n## A bump allocator over a caller's bytes. Only the last block can be resized or\n## released; everything goes away together when the buffer does.\npub struct FixedBuffer: Allocator:\n    var data: u8[]\n    var used: usize\n\n    pub static func over(buffer: u8[]) -> FixedBuffer:\n        return FixedBuffer(data = buffer, used = 0)\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]?:\n        if size == 0:\n            return self.data[..<0]\n        let align = alignment if alignment > 0 else 1\n        let start = (self.used + align - 1) // align * align\n        if start + size > self.data.length:\n            note_refusal(\"fixed buffer\", size, align, self.used)\n            return none\n        self.used = start + size\n        return self.data[start..<self.used]\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        let start = (usize)block.data - (usize)self.data.data\n        if start + block.length != self.used:\n            return false\n        if start + size > self.data.length:\n            return false\n        self.used = start + size\n        return true\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        let start = (usize)block.data - (usize)self.data.data\n        if start + block.length == self.used:\n            self.used = start\n\n## The C library's heap.\npub struct CAllocator: Allocator:\n    var unused: u8\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        var align = alignment if alignment > 8 else 8\n        var p: void*? = none\n        if posix_memalign(&p, align, size) != 0:\n            note_refusal(\"heap\", size, align, 0)\n            return none\n        let block = p else return none\n        return u8[]((u8*)block, size)\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        if not diagnostic:\n            c_free(block.data)\n            return\n        # the diagnostic profile (\302\24719.4): the block is filled with a pattern and held back, so\n        # a use after release reads the pattern rather than the next allocation\n        discard(memset(block.data, 221, block.length))\n        let slot = quarantine_next % quarantine.length\n        if let old = quarantine[slot]:\n            c_free(old.data)\n        quarantine[slot] = block\n        quarantine_next += 1\n\n## Bump allocation over a parent allocator, released all at once by `reset` or `destroy`\n## (\302\24712.4, \302\24724.3). One thread at a time.\npub struct Arena: Allocator:\n    var parent: Allocator\n    var block: u8[]\n    var used: usize\n\n    pub static func over(parent: Allocator, capacity: usize) -> Arena!:\n        let block = parent.allocate(capacity, 16) else error(exhausted, \"memory.exhausted\")\n        return Arena(parent = parent, block = block, used = 0)\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]?:\n        if size == 0:\n            return self.block[..<0]\n        let align = alignment if alignment > 0 else 1\n        let base = (usize)self.block.data\n        let start = ((base + self.used + align - 1) // align * align) - base\n        let end = start +? size else return none\n        if end > self.block.length:\n            note_refusal(\"arena\", size, align, self.used)\n            return none\n        self.used = end\n        return self.block[start..<end]\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        if size == block.length:\n            return true\n        if block.length == 0:\n            return false\n        # the last block may grow or shrink in place\n        let start = (usize)block.data - (usize)self.block.data\n        if start + block.length != self.used or start + size > self.block.length:\n            return false\n        self.used = start + size\n        return true\n\n    pub mutating func release(block: u8[]):\n        if diagnostic and block.length > 0:\n            discard(memset(block.data, 221, block.length))    # an arena releases all at once\n\n    ## What has been handed out since the last reset, and what the arena holds in all.\n    pub func in_use() -> usize:\n        return self.used\n    pub func capacity() -> usize:\n        return self.block.length\n\n    ## Forget every allocation; the storage is reused from its start.\n    pub mutating func reset():\n        self.used = 0\n\n    ## Give the storage back to the parent; the arena is empty afterwards.\n    pub mutating func destroy():\n        self.parent.release(self.block)\n        self.block = self.block[..<0]\n        self.used = 0\n\n## Whole pages from the host, each block its own mapping (\302\24712.4). Safe from several threads.\npub struct PageAllocator: Allocator:\n    var unused: u8\n\n    pub mutating func allocate(size: usize, alignment: usize) -> u8[]?:\n        if size == 0:\n            return u8[]((u8*)8, 0)\n        let page = (usize)getpagesize()\n        if alignment > page:\n            note_refusal(\"page allocator\", size, alignment, 0)\n            return none\n        let rounded = (size + page - 1) // page * page\n        let mapped = mmap(none, rounded, 3, private_anonymous, -1, 0) else return none\n        if (usize)mapped == 18446744073709551615:\n            note_refusal(\"page allocator\", size, alignment, 0)\n            return none\n        return u8[]((u8*)mapped, rounded)\n\n    pub mutating func resize(block: u8[], size: usize) -> bool:\n        return size <= block.length\n\n    pub mutating func release(block: u8[]):\n        if block.length == 0:\n            return\n        if diagnostic:\n            discard(memset(block.data, 221, block.length))\n        discard(munmap(block.data, block.length))\n\nextern func mmap(address: void*?, length: usize, protection: i32, flags: i32, descriptor: i32, offset: i64) -> void*?\n## `MAP_PRIVATE | MAP_ANON`: `MAP_ANON` is 0x1000 on macOS and 0x20 on Linux; the\n## protection `PROT_READ | PROT_WRITE` is 3 on both.\nlet private_anonymous: i32 = 4098 if platform.macos else 34\nextern func munmap(address: void*, length: usize) -> i32\nextern func getpagesize() -> i32\n\n## The heap refusing a request is rare and worth a line on standard error: what was asked,\n## so an exhaustion in the field says more than its error code. A fixed buffer running out\n## is ordinary and says nothing.\nfunc note_refusal(who: str, size: usize, alignment: usize, used: usize):\n    var text: u8[160]\n    let line = format(text, f\"memory: the {who} refused {size} bytes at alignment {alignment} (used {used})\\n\") catch failure:\n        return\n    discard(write_bytes(2, line.bytes.data, line.length))\n\nextern func write_bytes as \"write\"(descriptor: i32, buffer: const void*, count: usize) -> isize\n\n## `--profile diagnostic`: set by the startup shim before `startup` runs.\npub var diagnostic: bool\n\n## An allocation the diagnostic profile recorded (\302\24719.4): the block, its size, and where.\npub struct Site:\n    pub var address: void*?\n    pub var size: usize\n    pub var function: str\n    pub var line: u32\n\nvar sites: Site[256]\nvar site_next: usize\n\n## Called by the compiled program after each allocation under `--profile diagnostic`.\npub func note_site(address: void*?, size: usize, function: str, line: u32):\n    sites[site_next % sites.length] = Site(address = address, size = size, function = function, line = line)\n    site_next += 1\n\n## The allocations recorded so far, the most recent 256 at most, oldest first.\npub func allocation_sites() -> const Site[]:\n    let held = site_next if site_next < sites.length else sites.length\n    return sites[..<held]\n## The released blocks the diagnostic profile still holds, oldest freed first.\nvar quarantine: (u8[]?)[64]\nvar quarantine_next: usize\n\npub let exhausted: ErrorCode = ErrorCode.package(1)\npub let unset: ErrorCode = ErrorCode.package(2)\n\nvar c_allocator: CAllocator\n## The current allocator of this thread (\302\24712.3) and the process's initial one.\npub local var allocator: Allocator\npub var heap: Allocator\n\n## Run by the startup shim before `main`, and by `thread.spawn` in a new thread.\npub func startup():\n    heap = &c_allocator\n    allocator = heap\n\npub func copy[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        discard(memcpy(target.data, source.data, count * sizeof(T)))\n\npub func move[T](target: T[], source: const T[], count: usize):\n    if count > target.length or count > source.length:\n        trap(\"index out of bounds\")\n    if count > 0:\n        discard(memmove(target.data, source.data, count * sizeof(T)))\n\npub func set(target: u8[], value: u8):\n    if target.length > 0:\n        discard(memset(target.data, (i32)value, target.length))\n\npub func read[T](address: const void*) -> T:\n    var value: T = ---\n    discard(memcpy(&value, address, sizeof(T)))\n    return value\n\npub func write[T](address: void*, value: T):\n    var copy_of = value\n    discard(memcpy(address, &copy_of, sizeof(T)))\n\n## `block` with `size` bytes: in place when the current allocator can, else a\n## new block with the old bytes copied and the old block released.\npub func grow(block: u8[], size: usize) -> u8[]!:\n    if allocator.resize(block, size):\n        return u8[](block.data, size)\n    let fresh = allocator.allocate(size, 8) else error(exhausted, \"memory.exhausted\")\n    let keep = block.length if block.length < size else size\n    if keep > 0:\n        discard(memcpy(fresh.data, block.data, keep))\n    allocator.release(block)\n    return fresh\n", 10440})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"io", 2}), .text = ((lb_str){"import c\nimport core\nextern func fwrite(data: const void*, size: usize, count: usize, stream: void*) -> usize\nextern func fflush(stream: void*?) -> i32\nextern func fdopen(descriptor: i32, mode: c.str) -> void*?\n\n## The standard sink (\302\24714.4).\npub interface Writer:\n    mutating func write(data: const u8[]) -> usize!\n\n## A compile-time source position, the value of `luce.location`.\npub struct Location:\n    pub var file: str\n    pub var line: u32\n    pub var function: str\n\npub let closed: ErrorCode = ErrorCode.package(3)\n\n## A C stream. Every write is flushed so that it never reorders against `print`.\npub struct File: Writer:\n    var descriptor: i32\n    var stream: void*?\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if self.stream == none:\n            self.stream = fdopen(self.descriptor, \"w\")\n        let stream = self.stream else error(closed, \"the stream could not be opened\")\n        discard(fflush(none))\n        var written: usize = 0\n        if data.length > 0:\n            written = fwrite(data.data, 1, data.length, stream)\n        discard(fflush(stream))\n        if written != data.length:\n            error(closed, \"the stream refused the bytes\")\n        return written\n\nvar out_file: File = File(descriptor = 1, stream = none)\nvar err_file: File = File(descriptor = 2, stream = none)\n\npub func stdout() -> Writer:\n    return &out_file\n\npub func stderr() -> Writer:\n    return &err_file\n\npub let full: ErrorCode = ErrorCode.package(4)\n\n## The sink a formatted string offers a `Display` value (\302\24714.4): it appends to the buffer\n## the compiler is filling, and fails once that buffer is full, as `format` then does.\npub struct FormatSink: Writer:\n    var buffer: core.FormatBuffer*\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if core.format_put(self.buffer, data.data, data.length) != 0:\n            error(full, \"the buffer is full\")\n        return data.length\n\n## The process's directories (\302\24716.6): `from io import path`, then `path.user()`. Each is\n## a `str` view of environment storage the system owns, or fresh storage from the current\n## allocator where one has to be built.\npub struct path:\n    var unused: u8\n\n    ## The user's home directory: `$HOME`.\n    pub static func user() -> str!:\n        let home = getenv(\"HOME\") else error(io_path_failed, \"no home directory\")\n        return (str)home\n\n    pub static func home() -> str!:\n        return try path.user()\n\n    ## Where temporary files go: `$TMPDIR`, else `/tmp`.\n    pub static func temp() -> str:\n        let dir = getenv(\"TMPDIR\") else return \"/tmp\"\n        return (str)dir\n\n    ## Where configuration lives: `$XDG_CONFIG_HOME`, else `$HOME/.config`.\n    pub static func config() -> str!:\n        if let set = getenv(\"XDG_CONFIG_HOME\"):\n            return (str)set\n        let home = try path.user()\n        let buffer = try alloc u8[home.length + 8]\n        return try format(buffer, f\"{home}/.config\")\n\nextern func getenv(name: c.str) -> c.str?\npub let io_path_failed: ErrorCode = ErrorCode.package(13)\n", 3035})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"luce", 4}), .text = ((lb_str){"## The derived bounds of \302\24714.4: every type with `==` is Equatable, every hashable\n## one Hashable, every ordered one Comparable. Nothing implements them by hand.\n\nimport io\n\npub interface Equatable:\n    func equals(other: void*) -> bool\npub interface Hashable:\n    func hashed() -> u64\npub interface Comparable:\n    func compare(other: void*) -> i64\n\n## The protocols `for` consumes (\302\2478.3, \302\24714.4): a value iterator answers each element\n## until `none`; an iterable answers a fresh iterator of its own concrete type.\npub interface Iterator[T]:\n    mutating func next() -> T?\npub interface Iterable[T, I: Iterator[T]]:\n    func iterator() -> I\n\n## A value that writes itself to a sink (\302\24714.4); formatted strings call it for each field.\npub interface Display:\n    func display(sink: io.Writer) -> !\n\n## Compile-time facts about the use site; the backend replaces them (\302\2479.1).\npub let file: str = \"\"\npub let line: u32 = 0\npub let function: str = \"\"\npub let location: io.Location = io.Location(file = \"\", line = 0, function = \"\")\n", 1030})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"atomic", 6}), .text = ((lb_str){"## Memory orderings for the operations of `@T` (\302\24715.1).\npub enum Ordering as u8:\n    relaxed = 1\n    acquire = 2\n    release = 3\n    acq_rel = 4\n    seq_cst = 5\n\n## A standalone fence; the backend supplies the instruction.\npub func fence(order: Ordering):\n    discard(order)\n", 276})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"thread", 6}), .text = ((lb_str){"import memory\n\nextern func pthread_create(thread: void*?*, attributes: void*?, start: func(void*) -> void*?, argument: void*) -> i32\nextern func pthread_join(thread: void*, result: void*?*?) -> i32\nextern func pthread_detach(thread: void*) -> i32\nextern func pthread_self() -> void*\nextern func sched_yield() -> i32\nextern func nanosleep(request: const Duration*, remaining: Duration*?) -> i32\n\nextern struct Duration:\n    seconds: i64\n    nanoseconds: i64\n\npub let failed: ErrorCode = ErrorCode.package(5)\n\n## A running thread; the zero value is no thread at all, so arrays of handles exist.\npub struct Handle:\n    var id: void*?\n\n    pub func join() -> !:\n        let id = self.id else error(failed, \"no thread to join\")\n        if pthread_join(id, none) != 0:\n            error(failed, \"join\")\n\n    pub func detach():\n        let id = self.id else return\n        discard(pthread_detach(id))\n\n## What a new thread starts with: the entry, its context, and the allocator rule of \302\24715.3.\nstruct Start:\n    var entry: func(void*?) -> unit\n    var context: void*?\n\nfunc trampoline(raw: void*) -> void*?:\n    let start = (Start*)raw\n    memory.allocator = memory.heap\n    let entry = start.entry\n    let context = start.context\n    free(start) in memory.heap\n    entry(context)\n    return none\n\npub func spawn(entry: func(void*?) -> unit, context: void*?, stack: usize = 0, name: str = \"\") -> Handle!:\n    let start = try new Start(entry = entry, context = context) in memory.heap\n    var id: void*? = none\n    if pthread_create(&id, none, trampoline, (void*)start) != 0:\n        free(start) in memory.heap\n        error(failed, \"spawn\")\n    let thread = id else error(failed, \"spawn\")\n    discard(stack)\n    discard(name.length)\n    return Handle(id = thread)\n\npub func current() -> Handle:\n    return Handle(id = pthread_self())\n\n## A hint to the processor inside a spin loop.\npub func pause():\n    asm arm64:\n        yield\n    asm x86_64:\n        pause\n\npub func yield():\n    discard(sched_yield())\n\npub func sleep(milliseconds: u64):\n    var request = Duration(seconds = (i64)(milliseconds // 1000), nanoseconds = (i64)(milliseconds % 1000) * 1000000)\n    discard(nanosleep(&request, none))\n", 2191})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"sync", 4}), .text = ((lb_str){"import platform\n\n## macOS: the `ulock` calls libSystem builds its own locks on.\nextern func __ulock_wait(operation: u32, address: void*, value: u64, timeout: u32) -> i32\nextern func __ulock_wake(operation: u32, address: void*, wake_value: u64) -> i32\n## Linux: the futex system call, through `syscall`; the number is the architecture's.\nextern func syscall(number: i64, ...) -> i64\n\nlet compare_and_wait: u32 = 1\nlet wake_all: u32 = 256\nlet futex_number: i64 = 98 if platform.arm64 else 202\nlet futex_wait_private: i32 = 128\nlet futex_wake_private: i32 = 129\n\n## Sleep in the kernel while the word at `address` still holds `value`; a change\n## or a wake returns, and so may nothing at all, so every caller loops.\nfunc sleep_on(address: void*, value: u32):\n    if platform.macos:\n        discard(__ulock_wait(compare_and_wait, address, (u64)value, 0))\n    else:\n        let no_timeout: void*? = none\n        discard(syscall(futex_number, address, futex_wait_private, value, no_timeout))\n\nfunc wake_one(address: void*):\n    if platform.macos:\n        discard(__ulock_wake(compare_and_wait, address, 0))\n    else:\n        discard(syscall(futex_number, address, futex_wake_private, 1))\n\nfunc wake_every(address: void*):\n    if platform.macos:\n        discard(__ulock_wake(compare_and_wait | wake_all, address, 0))\n    else:\n        discard(syscall(futex_number, address, futex_wake_private, 2147483647))\n\n## A lock whose waiters sleep: zero is unlocked, so `var lock: Mutex` is ready to\n## use; one is locked; two is locked with someone asleep on it.\npub struct Mutex:\n    var state: @u32\n\n    pub mutating func lock():\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        if taken:\n            return\n        var current = seen\n        if current != 2:\n            current = self.state.swap(2, .acquire)\n        while current != 0:\n            sleep_on((void*)&self.state, 2)\n            current = self.state.swap(2, .acquire)\n\n    pub mutating func unlock():\n        if self.state.swap(0, .release) == 2:\n            wake_one((void*)&self.state)\n\n    pub mutating func try_lock() -> bool:\n        let (taken, seen) = self.state.cas(0, 1, .acquire, .relaxed)\n        discard(seen)\n        return taken\n\n## A sequence number waiters watch; every signal advances it and wakes.\npub struct Condition:\n    var sequence: @u32\n\n    pub mutating func wait(mutex: Mutex*):\n        let seen = self.sequence.load(.acquire)\n        mutex.unlock()\n        sleep_on((void*)&self.sequence, seen)\n        mutex.lock()\n\n    pub mutating func signal():\n        discard(self.sequence.add(1, .release))\n        wake_one((void*)&self.sequence)\n\n    pub mutating func broadcast():\n        discard(self.sequence.add(1, .release))\n        wake_every((void*)&self.sequence)\n\n## Runs its function exactly once; later callers wait for the first to finish.\npub struct Once:\n    var state: @u32\n\n    pub mutating func run(function: func() -> unit):\n        let (first, seen) = self.state.cas(0, 1, .acq_rel, .acquire)\n        discard(seen)\n        if first:\n            function()\n            self.state.store(2, .release)\n            wake_every((void*)&self.state)\n            return\n        while self.state.load(.acquire) != 2:\n            sleep_on((void*)&self.state, 1)\n\n## A counting semaphore whose waiters sleep.\npub struct Semaphore:\n    var count: @u32\n\n    pub mutating func acquire():\n        while true:\n            let n = self.count.load(.acquire)\n            if n > 0:\n                let (taken, seen) = self.count.cas(n, n - 1, .acq_rel, .relaxed)\n                discard(seen)\n                if taken:\n                    return\n            else:\n                sleep_on((void*)&self.count, 0)\n\n    pub mutating func release():\n        discard(self.count.add(1, .release))\n        wake_one((void*)&self.count)\n", 3823})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"files", 5}), .text = ((lb_str){"import c\nimport memory\nimport platform\n\nextern func open(path: c.str, flags: i32, ...) -> i32\nextern func close(descriptor: i32) -> i32\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func c_write as \"write\"(descriptor: i32, buffer: const void*, count: usize) -> isize\nextern func lseek(descriptor: i32, offset: i64, whence: i32) -> i64\nextern func opendir(path: c.str) -> void*?\nextern func readdir_macos as \"readdir\"(directory: void*) -> MacEntry*?\nextern func readdir_linux as \"readdir\"(directory: void*) -> LinuxEntry*?\nextern func closedir(directory: void*) -> i32\n\n## A directory entry as macOS lays it out (`struct dirent`, 64-bit inodes).\nextern struct MacEntry:\n    inode: u64\n    seek: u64\n    length: u16\n    name_length: u16\n    kind: u8\n    name: u8[1024]\n\n## A directory entry as Linux lays it out: the name is NUL-terminated, not counted.\nextern struct LinuxEntry:\n    inode: u64\n    offset: i64\n    length: u16\n    kind: u8\n    name: u8[256]\n\n## The next entry's name, or none at the end; `.` and `..` are entries like any other.\nfunc next_entry(directory: void*) -> str?:\n    if platform.macos:\n        let entry = readdir_macos(directory) else return none\n        return (str)entry.name[..<(usize)entry.name_length]\n    let entry = readdir_linux(directory) else return none\n    var n: usize = 0\n    while n < entry.name.length and entry.name[n] != 0:\n        n += 1\n    return (str)entry.name[..<n]\n\n## `open` flags: macOS keeps the BSD values, Linux its own (\302\24719.5).\nlet read_only: i32 = 0\nlet write_only: i32 = 1\nlet create: i32 = 512 if platform.macos else 64\nlet truncate: i32 = 1024 if platform.macos else 512\nlet seek_end: i32 = 2\nlet seek_set: i32 = 0\n\npub let missing: ErrorCode = ErrorCode.package(6)\n\n## Whether `path` can be opened for reading.\npub func exists(path: c.str) -> bool:\n    let descriptor = open(path, read_only)\n    if descriptor < 0:\n        return false\n    discard(close(descriptor))\n    return true\npub let failed: ErrorCode = ErrorCode.package(7)\n\n## The whole file, allocated from the current allocator.\npub func read(path: c.str) -> u8[]!:\n    let fd = open(path, read_only)\n    if fd < 0:\n        error(missing, \"missing\")\n    let size = lseek(fd, 0, seek_end)\n    if size < 0 or lseek(fd, 0, seek_set) < 0:\n        discard(close(fd))\n        error(failed, \"the file cannot be read\")\n    let bytes = alloc u8[(usize)size] catch failure:\n        discard(close(fd))\n        error(memory.exhausted, \"memory.exhausted\")\n    var got: usize = 0\n    while got < bytes.length:\n        let n = c_read(fd, bytes[got..].data, bytes.length - got)\n        if n < 0:\n            discard(close(fd))\n            error(failed, \"the file cannot be read\")\n        if n == 0:\n            break\n        got += (usize)n\n    discard(close(fd))\n    return bytes[..<got]\n\npub func write(path: c.str, data: const u8[]) -> !:\n    let fd = open(path, write_only | create | truncate, 420)\n    if fd < 0:\n        error(missing, \"missing\")\n    var done: usize = 0\n    while done < data.length:\n        let n = c_write(fd, data[done..].data, data.length - done)\n        if n <= 0:\n            discard(close(fd))\n            error(failed, \"write\")\n        done += (usize)n\n    discard(close(fd))\n\n## The names in a directory, sorted, allocated from the current allocator.\npub func list(path: c.str) -> str[]!:\n    let dir = opendir(path) else error(missing, \"missing\")\n    var names = try alloc str[16]\n    var count: usize = 0\n    while let name = next_entry(dir):\n        if name == \".\" or name == \"..\":\n            continue\n        if count == names.length:\n            let grown = try alloc str[names.length * 2]\n            memory.copy(grown, names, count)\n            names = grown\n        let copy = try alloc u8[name.length + 1]\n        memory.copy(copy, name.bytes, name.length)\n        copy[name.length] = 0\n        names[count] = (str)copy[..<name.length]\n        count += 1\n    discard(closedir(dir))\n    # insertion sort by bytes; directories are small\n    var i: usize = 1\n    while i < count:\n        let item = names[i]\n        var j = i\n        while j > 0 and item < names[j - 1]:\n            names[j] = names[j - 1]\n            j -= 1\n        names[j] = item\n        i += 1\n    return names[..<count]\n", 4282})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"process", 7}), .text = ((lb_str){"import c\nimport memory\nimport platform\n\nextern func pipe(descriptors: i32*) -> i32\nextern func fork() -> i32\nextern func dup2(from_fd: i32, to_fd: i32) -> i32\nextern func close(descriptor: i32) -> i32\nextern func execvp(program: c.str, arguments: void*?*) -> i32\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func _exit(code: i32) -> never\nextern func waitpid(pid: i32, status: i32*, options: i32) -> i32\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func poll(descriptors: Poll*, count: u32, timeout: i32) -> i32\nextern func fcntl(descriptor: i32, command: i32, ...) -> i32\n\nextern struct Poll:\n    descriptor: i32\n    events: i16\n    returned: i16\n\nlet poll_in: i16 = 1\nlet poll_hang_up: i16 = 16\nlet poll_error: i16 = 8\nlet set_flags: i32 = 4\n## `O_NONBLOCK`: 4 on macOS, 2048 on Linux.\nlet non_blocking: i32 = 4 if platform.macos else 2048\n\npub let failed: ErrorCode = ErrorCode.package(8)\n\n## A captured stream: bytes in the current allocator.\nstruct Capture:\n    var descriptor: i32\n    var data: u8[]\n    var used: usize\n    var open: bool\n\n    mutating func pull() -> !:\n        if self.data.length - self.used < 256:\n            let room = 1024 if self.data.length == 0 else self.data.length * 2\n            self.data = try memory.grow(self.data, room)\n        let n = c_read(self.descriptor, self.data[self.used..].data, self.data.length - self.used)\n        if n == 0:\n            self.open = false\n        elif n > 0:\n            self.used += (usize)n\n\n## Run `program` with `arguments`, wait for it, and answer its exit status and\n## what it wrote to its standard output and error.\npub func run(program: c.str, arguments: const c.str[]) -> (i32, str, str)!:\n    var out_pipe: i32[2]\n    var err_pipe: i32[2]\n    if pipe((i32*)&out_pipe) != 0:\n        error(failed, \"run\")\n    if pipe((i32*)&err_pipe) != 0:\n        error(failed, \"run\")\n    let pid = fork()\n    if pid < 0:\n        error(failed, \"run\")\n    if pid == 0:\n        discard(close(out_pipe[0]))\n        discard(close(err_pipe[0]))\n        if dup2(out_pipe[1], 1) < 0 or dup2(err_pipe[1], 2) < 0:\n            _exit(127)\n        discard(close(out_pipe[1]))\n        discard(close(err_pipe[1]))\n        let argv = alloc void*?[arguments.length + 2] catch failure:\n            _exit(127)\n        argv[0] = (void*)program\n        var i: usize = 0\n        while i < arguments.length:\n            argv[i + 1] = (void*)arguments[i]\n            i += 1\n        argv[arguments.length + 1] = none\n        discard(execvp(program, argv.data))\n        _exit(127)\n    discard(close(out_pipe[1]))\n    discard(close(err_pipe[1]))\n    discard(fcntl(out_pipe[0], set_flags, non_blocking))\n    discard(fcntl(err_pipe[0], set_flags, non_blocking))\n    var out = Capture(descriptor = out_pipe[0], data = u8[]((u8*)8, 0), used = 0, open = true)\n    var err = Capture(descriptor = err_pipe[0], data = u8[]((u8*)8, 0), used = 0, open = true)\n    while out.open or err.open:\n        var watched: Poll[2] = ---\n        watched[0] = Poll(descriptor = out.descriptor if out.open else -1, events = poll_in, returned = 0)\n        watched[1] = Poll(descriptor = err.descriptor if err.open else -1, events = poll_in, returned = 0)\n        if poll((Poll*)&watched, 2, -1) < 0:\n            continue\n        if out.open and (watched[0].returned & (poll_in | poll_hang_up | poll_error)) != 0:\n            try out.pull()\n        if err.open and (watched[1].returned & (poll_in | poll_hang_up | poll_error)) != 0:\n            try err.pull()\n    discard(close(out_pipe[0]))\n    discard(close(err_pipe[0]))\n    var status: i32 = 0\n    if waitpid(pid, &status, 0) < 0:\n        error(failed, \"run\")\n    if (status & 127) != 0:\n        error(failed, \"the program was stopped by a signal\")\n    return ((status >> 8) & 255, (str)out.data[..<out.used], (str)err.data[..<err.used])\n\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 3913})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"strings", 7}), .text = ((lb_str){"import c\n## Text operations over `str` views; what allocates says so and uses the current allocator.\n\nimport memory\nfrom io import Writer\n\npub func starts_with(text: str, prefix: str) -> bool:\n    if prefix.length > text.length:\n        return false\n    return (str)text.bytes[..<prefix.length] == prefix\n\npub func ends_with(text: str, suffix: str) -> bool:\n    if suffix.length > text.length:\n        return false\n    return (str)text.bytes[text.length - suffix.length..] == suffix\n\n## The byte offset of the first `needle` in `text`.\npub func find(text: str, needle: str) -> usize?:\n    if needle.length > text.length:\n        return none\n    var i: usize = 0\n    while i + needle.length <= text.length:\n        if (str)text.bytes[i..<i + needle.length] == needle:\n            return i\n        i += 1\n    return none\n\n## The byte offset of the last `byte` in `text`.\npub func last(text: str, byte: u8) -> usize?:\n    var i = text.length\n    while i > 0:\n        i -= 1\n        if text.bytes[i] == byte:\n            return i\n    return none\n\npub func contains(text: str, needle: str) -> bool:\n    return find(text, needle) != none\n\nfunc is_space(byte: u8) -> bool:\n    return byte == ' ' or byte == '\\n' or byte == '\\t' or byte == '\\r'\n\n## `text` without leading and trailing spaces, tabs, and line ends: a view.\npub func trim(text: str) -> str:\n    var start: usize = 0\n    var end = text.length\n    let b = text.bytes\n    while start < end and is_space(b[start]):\n        start += 1\n    while end > start and is_space(b[end - 1]):\n        end -= 1\n    return (str)b[start..<end]\n\n## `text` split at every `separator`, as views into it, in the current allocator.\npub func split(text: str, separator: u8) -> str[]!:\n    var count: usize = 1\n    for b in text.bytes:\n        if b == separator:\n            count += 1\n    let parts = try alloc str[count]\n    var n: usize = 0\n    var start: usize = 0\n    var i: usize = 0\n    let b = text.bytes\n    while i < b.length:\n        if b[i] == separator:\n            parts[n] = (str)b[start..<i]\n            n += 1\n            start = i + 1\n        i += 1\n    parts[n] = (str)b[start..]\n    return parts\n\n## The pieces joined with `separator` between them, in the current allocator.\npub func join(pieces: const str[], separator: str) -> str!:\n    var total: usize = 0\n    var i: usize = 0\n    while i < pieces.length:\n        total += pieces[i].length\n        if i + 1 < pieces.length:\n            total += separator.length\n        i += 1\n    let out = try alloc u8[total + 1]\n    var n: usize = 0\n    i = 0\n    while i < pieces.length:\n        memory.copy(out[n..], pieces[i].bytes, pieces[i].length)\n        n += pieces[i].length\n        if i + 1 < pieces.length:\n            memory.copy(out[n..], separator.bytes, separator.length)\n            n += separator.length\n        i += 1\n    out[n] = 0\n    return (str)out[..<n]\n\n## A copy of `text` in the current allocator, NUL-terminated so it may be a `c.str`.\npub func copy(text: str) -> str!:\n    let out = try alloc u8[text.length + 1]\n    memory.copy(out, text.bytes, text.length)\n    out[text.length] = 0\n    return (str)out[..<text.length]\n\n## A decimal integer, with an optional sign; none when the text is not one.\npub func to_i64(text: str) -> i64?:\n    let b = text.bytes\n    if b.length == 0:\n        return none\n    var i: usize = 0\n    var negative = false\n    if b[0] == '-' or b[0] == '+':\n        negative = b[0] == '-'\n        i = 1\n    if i >= b.length:\n        return none\n    var value: i64 = 0\n    while i < b.length:\n        let byte = b[i]\n        if byte < '0' or byte > '9':\n            return none\n        let digit = (i64)(byte - '0')\n        let next = value *? 10 else return none\n        value = next +? digit else return none\n        i += 1\n    return 0 - value if negative else value\n\n## ASCII case folding; other bytes pass through.\npub func to_upper(text: str) -> str!:\n    let out = try alloc u8[text.length + 1]\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b - 32 if b >= 'a' and b <= 'z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\npub func to_lower(text: str) -> str!:\n    let out = try alloc u8[text.length + 1]\n    var i: usize = 0\n    for b in text.bytes:\n        out[i] = b + 32 if b >= 'A' and b <= 'Z' else b\n        i += 1\n    out[i] = 0\n    return (str)out[..<i]\n\n## Text built piece by piece in the current allocator.\npub struct Builder: Writer:\n    var data: u8[]\n    var used: usize\n\n    pub static func create(capacity: usize) -> Builder!:\n        return Builder(data = try alloc u8[capacity if capacity > 0 else 64], used = 0)\n\n    pub mutating func write(data: const u8[]) -> usize!:\n        if self.used + data.length >= self.data.length:\n            var room = self.data.length * 2\n            while room <= self.used + data.length:\n                room = room * 2\n            self.data = try memory.grow(self.data, room)\n        memory.copy(self.data[self.used..], data, data.length)\n        self.used += data.length\n        return data.length\n\n    pub mutating func put(text: str) -> !:\n        discard(try self.write(text.bytes))\n\n    ## The text so far, NUL-terminated in the buffer; invalid after the next write.\n    pub mutating func view() -> str:\n        if self.used < self.data.length:\n            self.data[self.used] = 0\n        return (str)self.data[..<self.used]\n\n    pub mutating func clear():\n        self.used = 0\n", 5416})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"paths", 5}), .text = ((lb_str){"## File system paths as text, with `/` as the separator.\n\nimport memory\nimport strings\n\npub func is_absolute(path: str) -> bool:\n    return path.length > 0 and path.bytes[0] == '/'\n\n## Everything up to the last separator, or `.` when there is none.\npub func directory(path: str) -> str:\n    let cut = strings.last(path, '/') else return \".\"\n    if cut == 0:\n        return \"/\"\n    return (str)path.bytes[..<cut]\n\n## The last component.\npub func base(path: str) -> str:\n    let cut = strings.last(path, '/') else return path\n    return (str)path.bytes[cut + 1..]\n\n## The extension with its dot, or the empty text.\npub func extension(path: str) -> str:\n    let name = base(path)\n    let dot = strings.last(name, '.') else return \"\"\n    if dot == 0:\n        return \"\"\n    return (str)name.bytes[dot..]\n\n## The last component without its extension.\npub func stem(path: str) -> str:\n    let name = base(path)\n    let ext = extension(name)\n    return (str)name.bytes[..<name.length - ext.length]\n\n## `left/right`, in the current allocator; an absolute `right` wins.\npub func join(left: str, right: str) -> str!:\n    if is_absolute(right) or left.length == 0:\n        return try strings.copy(right)\n    let out = try alloc u8[left.length + right.length + 2]\n    var n: usize = 0\n    memory.copy(out, left.bytes, left.length)\n    n = left.length\n    if left.bytes[left.length - 1] != '/':\n        out[n] = '/'\n        n += 1\n    memory.copy(out[n..], right.bytes, right.length)\n    n += right.length\n    out[n] = 0\n    return (str)out[..<n]\n", 1533})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"math", 4}), .text = ((lb_str){"## The mathematical functions of the standard library (\302\24716.6): `import math` for\n## `math.sqrt(x)`, `from math import sqrt` for `sqrt(x)`. The float functions are the C\n## library's, declared here with the types Base gives them; the integer functions are Base.\nextern func c_floor as \"floor\"(x: f64) -> f64\nextern func c_ceil as \"ceil\"(x: f64) -> f64\nextern func c_round as \"round\"(x: f64) -> f64\nextern func c_trunc as \"trunc\"(x: f64) -> f64\nextern func c_sqrt as \"sqrt\"(x: f64) -> f64\nextern func c_cbrt as \"cbrt\"(x: f64) -> f64\nextern func c_hypot as \"hypot\"(x: f64, y: f64) -> f64\nextern func c_fmod as \"fmod\"(x: f64, y: f64) -> f64\nextern func c_pow as \"pow\"(x: f64, y: f64) -> f64\nextern func c_exp as \"exp\"(x: f64) -> f64\nextern func c_exp2 as \"exp2\"(x: f64) -> f64\nextern func c_log as \"log\"(x: f64) -> f64\nextern func c_log2 as \"log2\"(x: f64) -> f64\nextern func c_log10 as \"log10\"(x: f64) -> f64\nextern func c_sin as \"sin\"(x: f64) -> f64\nextern func c_cos as \"cos\"(x: f64) -> f64\nextern func c_tan as \"tan\"(x: f64) -> f64\nextern func c_asin as \"asin\"(x: f64) -> f64\nextern func c_acos as \"acos\"(x: f64) -> f64\nextern func c_atan as \"atan\"(x: f64) -> f64\nextern func c_atan2 as \"atan2\"(y: f64, x: f64) -> f64\nextern func c_sinh as \"sinh\"(x: f64) -> f64\nextern func c_cosh as \"cosh\"(x: f64) -> f64\nextern func c_tanh as \"tanh\"(x: f64) -> f64\n\npub let pi: f64 = 3.141592653589793\npub let tau: f64 = 6.283185307179586\npub let e: f64 = 2.718281828459045\n## Built from bits so that no constant expression needs to overflow.\npub let infinity: f64 = f64.bits(9218868437227405312)\npub let nan: f64 = f64.bits(9221120237041090560)\n\n## Rounding: `floor` toward negative infinity, `ceil` toward positive, `round` to the\n## nearest with halves away from zero, `trunc` toward zero.\npub func floor(x: f64) -> f64:\n    return c_floor(x)\npub func ceil(x: f64) -> f64:\n    return c_ceil(x)\npub func round(x: f64) -> f64:\n    return c_round(x)\npub func trunc(x: f64) -> f64:\n    return c_trunc(x)\n\npub func sqrt(x: f64) -> f64:\n    return c_sqrt(x)\npub func cbrt(x: f64) -> f64:\n    return c_cbrt(x)\n## `sqrt(x * x + y * y)` without overflow in the squares.\npub func hypot(x: f64, y: f64) -> f64:\n    return c_hypot(x, y)\n## The remainder of `x / y` with the sign of `x`, as C's `fmod`.\npub func mod(x: f64, y: f64) -> f64:\n    return c_fmod(x, y)\npub func pow(x: f64, y: f64) -> f64:\n    return c_pow(x, y)\npub func exp(x: f64) -> f64:\n    return c_exp(x)\npub func exp2(x: f64) -> f64:\n    return c_exp2(x)\npub func log(x: f64) -> f64:\n    return c_log(x)\npub func log2(x: f64) -> f64:\n    return c_log2(x)\npub func log10(x: f64) -> f64:\n    return c_log10(x)\n\npub func sin(x: f64) -> f64:\n    return c_sin(x)\npub func cos(x: f64) -> f64:\n    return c_cos(x)\npub func tan(x: f64) -> f64:\n    return c_tan(x)\npub func asin(x: f64) -> f64:\n    return c_asin(x)\npub func acos(x: f64) -> f64:\n    return c_acos(x)\npub func atan(x: f64) -> f64:\n    return c_atan(x)\n## The angle of the point `(x, y)`, in all four quadrants.\npub func atan2(y: f64, x: f64) -> f64:\n    return c_atan2(y, x)\npub func sinh(x: f64) -> f64:\n    return c_sinh(x)\npub func cosh(x: f64) -> f64:\n    return c_cosh(x)\npub func tanh(x: f64) -> f64:\n    return c_tanh(x)\n\npub func is_nan(x: f64) -> bool:\n    return x != x\npub func is_finite(x: f64) -> bool:\n    return x - x == 0.0\npub func is_infinite(x: f64) -> bool:\n    return x == infinity or x == 0.0 - infinity\npub func abs(x: f64) -> f64:\n    return 0.0 - x if x < 0.0 else x\n## `-1.0`, `0.0`, or `1.0`; NaN answers NaN.\npub func sign(x: f64) -> f64:\n    if x < 0.0:\n        return -1.0\n    if x > 0.0:\n        return 1.0\n    return x\npub func min(a: f64, b: f64) -> f64:\n    return a if a < b else b\npub func max(a: f64, b: f64) -> f64:\n    return a if a > b else b\npub func clamp(x: f64, low: f64, high: f64) -> f64:\n    return low if x < low else (high if x > high else x)\n\n## The integer functions. `//` and `%` truncate toward zero as C does (\302\2477.2); these two\n## floor, so `div_floor(-7, 2)` is `-4` and `mod_floor(-7, 2)` is `1`.\npub func div_floor(a: i64, b: i64) -> i64:\n    let q = a // b\n    if (a % b != 0) and ((a < 0) != (b < 0)):\n        return q - 1\n    return q\npub func mod_floor(a: i64, b: i64) -> i64:\n    let r = a % b\n    if r != 0 and ((r < 0) != (b < 0)):\n        return r + b\n    return r\npub func iabs(a: i64) -> i64:\n    return 0 - a if a < 0 else a\npub func imin(a: i64, b: i64) -> i64:\n    return a if a < b else b\npub func imax(a: i64, b: i64) -> i64:\n    return a if a > b else b\npub func iclamp(x: i64, low: i64, high: i64) -> i64:\n    return low if x < low else (high if x > high else x)\n", 4638})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"time", 4}), .text = ((lb_str){"import platform\n\nextern func clock_gettime(clock: i32, out_time: Stamp*) -> i32\nextern func c_time as \"time\"(out_time: void*?) -> i64\n\nextern struct Stamp:\n    seconds: i64\n    nanoseconds: i64\n\n## `CLOCK_MONOTONIC`: 6 on macOS, 1 on Linux; `CLOCK_REALTIME` is 0 on both.\nlet monotonic: i32 = 6 if platform.macos else 1\nlet realtime: i32 = 0\n\n## Nanoseconds from an arbitrary origin, never going backwards.\npub func now() -> u64:\n    var stamp = Stamp(seconds = 0, nanoseconds = 0)\n    discard(clock_gettime(monotonic, &stamp))\n    return (u64)stamp.seconds * 1000000000 + (u64)stamp.nanoseconds\n\n## Seconds since the Unix epoch.\npub func unix() -> i64:\n    return c_time(none)\n\n## Nanoseconds elapsed since `start`, from `now()`.\npub func since(start: u64) -> u64:\n    let current = now()\n    return current - start if current > start else 0\n", 843})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"os", 2}), .text = ((lb_str){"## The operating system's view of the process (\302\24716.6): its environment, working\n## directory, identity, and host. Text comes back as `str` views of C storage that the\n## system owns; copy what must outlive the next call.\nimport c\nimport memory\nimport platform\n\nextern func getenv(name: c.str) -> c.str?\nextern func setenv(name: c.str, value: c.str, overwrite: i32) -> i32\nextern func unsetenv(name: c.str) -> i32\nextern func getcwd(buffer: u8*, size: usize) -> c.str?\nextern func chdir(path: c.str) -> i32\nextern func getpid() -> i32\nextern func getppid() -> i32\nextern func gethostname(buffer: u8*, size: usize) -> i32\nextern func c_exit as \"exit\"(code: i32) -> never\nextern func sysconf(name: i32) -> i64\nextern func getpagesize() -> i32\n\npub let failed: ErrorCode = ErrorCode.package(12)\n\n## The target, as constants a program branches on: `if os.arm64:`, `if os.linux and\n## os.x86_64:` (\302\24719.5); the compiler decides them from `--target`, so the branch a target\n## rules out is pruned (\302\24719.6).\npub let arm64: bool = platform.arm64\npub let x86_64: bool = platform.x86_64\npub let macos: bool = platform.macos\npub let linux: bool = platform.linux\npub let windows: bool = platform.windows\npub let posix: bool = platform.posix\npub let pointer_bits: u32 = platform.pointer_bits\npub let name: str = platform.name\n\n## `_SC_NPROCESSORS_ONLN`: 58 on macOS, 84 on Linux.\nlet processors_online: i32 = 58 if platform.macos else 84\n\n## The processors available to this process, at least one.\npub func cpus() -> u32:\n    let n = sysconf(processors_online)\n    return (u32)n if n > 0 else 1\n\npub func page_size() -> usize:\n    return (usize)getpagesize()\n\n## The value of an environment variable, or none when it is not set.\npub func env(name: c.str) -> str?:\n    let value = getenv(name) else return none\n    return (str)value\n\n## Set an environment variable for this process and the ones it starts.\npub func set_env(name: c.str, value: c.str) -> !:\n    if setenv(name, value, 1) != 0:\n        error(failed, \"the environment variable cannot be set\")\n\npub func unset_env(name: c.str) -> !:\n    if unsetenv(name) != 0:\n        error(failed, \"the environment variable cannot be unset\")\n\n## The working directory, in storage from the current allocator.\npub func cwd() -> str!:\n    let buffer = try alloc u8[4096]\n    let found = getcwd(buffer.data, buffer.length)\n    if found == none:\n        free(buffer)\n        error(failed, \"the working directory cannot be read\")\n    let path = found else trap(\"unreachable\")\n    return (str)path\n\npub func change_dir(path: c.str) -> !:\n    if chdir(path) != 0:\n        error(failed, \"the directory cannot be entered\")\n\npub func pid() -> i32:\n    return getpid()\n\npub func parent_pid() -> i32:\n    return getppid()\n\n## The host's name, in storage from the current allocator.\npub func hostname() -> str!:\n    let buffer = try alloc u8[256]\n    if gethostname(buffer.data, buffer.length) != 0:\n        free(buffer)\n        error(failed, \"the host name cannot be read\")\n    var n: usize = 0\n    while n < buffer.length and buffer[n] != 0:\n        n += 1\n    return (str)buffer[..<n]\n\n## Stop the process with `code`, running no deferred work.\npub func exit(code: i32) -> never:\n    c_exit(code)\n", 3219})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"testing", 7}), .text = ((lb_str){"## What a Base test runs under (\302\24716.5): a fixed-buffer allocator made current for\n## each test, a deterministic seed, and assertions that name what differed.\n\nimport memory\nfrom memory import Allocator, FixedBuffer\n\nvar arena_bytes: u8[1048576]\nvar arena: FixedBuffer\nvar saved: Allocator\nvar current_seed: u64 = 1\n\n## Called by the runner before each test.\npub func begin(index: u64):\n    arena = FixedBuffer.over(arena_bytes)\n    saved = memory.allocator\n    memory.allocator = &arena\n    current_seed = index * 2654435761 + 1\n\n## Called by the runner after each test.\npub func end():\n    memory.allocator = saved\n\n## A seed that is the same on every run of the same test.\npub func seed() -> u64:\n    return current_seed\n\n## The next pseudo-random value from the seed, and the seed advanced.\npub func random() -> u64:\n    var x = current_seed\n    x = x ^ (x << 13)\n    x = x ^ (x >> 7)\n    x = x ^ (x << 17)\n    current_seed = x\n    return x\n\npub func expect(condition: bool, message: str):\n    if not condition:\n        trap(message)\n\npub func expect_equal(actual: i64, expected: i64, message: str):\n    if actual != expected:\n        print(f\"expected {expected}, got {actual}: {message}\")\n        trap(message)\n\npub func expect_text(actual: str, expected: str, message: str):\n    if actual != expected:\n        print(f\"expected `{expected}`, got `{actual}`: {message}\")\n        trap(message)\n", 1397})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"net", 3}), .text = ((lb_str){"import c\nimport platform\nfrom io import Writer\n\nextern func socket(domain: i32, kind: i32, protocol: i32) -> i32\nextern func bind(descriptor: i32, address: const SocketAddress*, length: u32) -> i32\nextern func listen(descriptor: i32, backlog: i32) -> i32\nextern func accept(descriptor: i32, address: SocketAddress*?, length: u32*?) -> i32\nextern func connect(descriptor: i32, address: const SocketAddress*, length: u32) -> i32\nextern func send(descriptor: i32, data: const void*, length: usize, flags: i32) -> isize\nextern func recv(descriptor: i32, buffer: void*, length: usize, flags: i32) -> isize\nextern func sendto(descriptor: i32, data: const void*, length: usize, flags: i32, address: const SocketAddress*, address_length: u32) -> isize\nextern func recvfrom(descriptor: i32, buffer: void*, length: usize, flags: i32, address: SocketAddress*?, address_length: u32*?) -> isize\nextern func close(descriptor: i32) -> i32\nextern func setsockopt(descriptor: i32, level: i32, option: i32, value: const void*, length: u32) -> i32\nextern func getsockname(descriptor: i32, address: SocketAddress*, length: u32*) -> i32\nextern func getaddrinfo(host: c.str, service: c.str?, hints: const AddressInfo*?, result: AddressInfo*?*) -> i32\nextern func freeaddrinfo(info: AddressInfo*)\n\n## `sockaddr_in`: 16 bytes everywhere; macOS splits the first two into a length and a\n## one-byte family, Linux keeps a two-byte family. `family_word` reads and writes it.\nextern struct SocketAddress:\n    head: u16\n    port: u16\n    address: u32\n    zero: u8[8]\n\n## The first two bytes of `sockaddr_in` as one little-endian word: on macOS the length\n## byte (16) comes first and the family byte second, on Linux the family fills both.\nfunc family_word(family: u8) -> u16:\n    if platform.macos:\n        return (u16)16 | ((u16)family << 8)\n    return (u16)family\n\n## `addrinfo`: macOS puts the canonical name before the address, Linux after it.\nextern struct AddressInfo:\n    flags: i32\n    family: i32\n    kind: i32\n    protocol: i32\n    address_length: u32\n    fifth: void*?\n    sixth: void*?\n    next: AddressInfo*?\n\nfunc info_address(info: AddressInfo*) -> SocketAddress*?:\n    let raw = info.sixth if platform.macos else info.fifth\n    let p = raw else return none\n    return (SocketAddress*)p\n\nlet inet: i32 = 2\nlet stream: i32 = 1\nlet datagram: i32 = 2\n## `SOL_SOCKET` and `SO_REUSEADDR`: 65535 and 4 on macOS, 1 and 2 on Linux.\nlet socket_level: i32 = 65535 if platform.macos else 1\nlet reuse_address: i32 = 4 if platform.macos else 2\n\npub let failed: ErrorCode = ErrorCode.package(9)\npub let closed: ErrorCode = ErrorCode.package(10)\npub let unknown_host: ErrorCode = ErrorCode.package(11)\n\n## An IPv4 address and port, both in host order.\npub struct Address:\n    pub var ip: u32\n    pub var port: u16\n\n    pub static func loopback(port: u16) -> Address:\n        return Address(ip = 2130706433, port = port)\n\n    pub static func any(port: u16) -> Address:\n        return Address(ip = 0, port = port)\n\n    func raw() -> SocketAddress:\n        var zero: u8[8]\n        return SocketAddress(head = family_word(2), port = swap16(self.port), address = swap32(self.ip), zero = zero)\n\n    static func from_raw(raw: SocketAddress) -> Address:\n        return Address(ip = swap32(raw.address), port = swap16(raw.port))\n\n## Host to network byte order and back; the machine is little-endian.\nfunc swap16(value: u16) -> u16:\n    return (value << 8) | (value >> 8)\n\nfunc swap32(value: u32) -> u32:\n    return (value << 24) | ((value << 8) & 16711680) | ((value >> 8) & 65280) | (value >> 24)\n\n## The first IPv4 address of `host`.\npub func resolve(host: c.str, port: u16) -> Address!:\n    var hints = AddressInfo(flags = 0, family = inet, kind = stream, protocol = 0, address_length = 0, fifth = none, sixth = none, next = none)\n    var found: AddressInfo*? = none\n    if getaddrinfo(host, none, &hints, &found) != 0:\n        error(unknown_host, \"unknown host\")\n    let info = found else error(unknown_host, \"unknown host\")\n    let raw = info_address(info) else error(unknown_host, \"unknown host\")\n    var address = Address.from_raw(*raw)\n    address.port = port\n    freeaddrinfo(info)\n    return address\n\n## A bound TCP socket waiting for connections.\npub struct Listener:\n    var descriptor: i32\n\n    pub static func bind(address: Address) -> Listener!:\n        let fd = socket(inet, stream, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        var yes: i32 = 1\n        discard(setsockopt(fd, socket_level, reuse_address, &yes, 4))\n        let raw = address.raw()\n        if bind(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"bind\")\n        if listen(fd, 16) != 0:\n            discard(close(fd))\n            error(failed, \"listen\")\n        return Listener(descriptor = fd)\n\n    ## The address the socket ended up with; a port of zero asked for any free one.\n    pub func address() -> Address:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        discard(getsockname(self.descriptor, &raw, &length))\n        return Address.from_raw(raw)\n\n    pub func accept() -> Connection!:\n        let fd = accept(self.descriptor, none, none)\n        if fd < 0:\n            error(failed, \"accept\")\n        return Connection(descriptor = fd)\n\n    pub func close():\n        discard(close(self.descriptor))\n\n## One TCP connection; it is a `Writer`.\npub struct Connection: Writer:\n    ## The socket, for callers that poll or pass it on.\n    pub var descriptor: i32\n\n    pub static func connect(address: Address) -> Connection!:\n        let fd = socket(inet, stream, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        let raw = address.raw()\n        if connect(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"connect\")\n        return Connection(descriptor = fd)\n\n    ## Send every byte.\n    pub mutating func write(data: const u8[]) -> usize!:\n        var done: usize = 0\n        while done < data.length:\n            let n = send(self.descriptor, data[done..].data, data.length - done, 0)\n            if n <= 0:\n                error(closed, \"the connection closed\")\n            done += (usize)n\n        return done\n\n    ## Receive what is available, up to the buffer; zero means the peer closed.\n    pub func receive(buffer: u8[]) -> usize!:\n        let n = recv(self.descriptor, buffer.data, buffer.length, 0)\n        if n < 0:\n            error(closed, \"the connection closed\")\n        return (usize)n\n\n    pub func close():\n        discard(close(self.descriptor))\n\n## A UDP socket.\npub struct Datagram:\n    var descriptor: i32\n\n    pub static func bind(address: Address) -> Datagram!:\n        let fd = socket(inet, datagram, 0)\n        if fd < 0:\n            error(failed, \"socket\")\n        let raw = address.raw()\n        if bind(fd, &raw, 16) != 0:\n            discard(close(fd))\n            error(failed, \"bind\")\n        return Datagram(descriptor = fd)\n\n    pub func address() -> Address:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        discard(getsockname(self.descriptor, &raw, &length))\n        return Address.from_raw(raw)\n\n    pub func send_to(data: const u8[], address: Address) -> !:\n        let raw = address.raw()\n        if sendto(self.descriptor, data.data, data.length, 0, &raw, 16) < 0:\n            error(failed, \"send\")\n\n    pub func receive_from(buffer: u8[]) -> (usize, Address)!:\n        var raw = SocketAddress(head = 0, port = 0, address = 0, zero = [0, 0, 0, 0, 0, 0, 0, 0])\n        var length: u32 = 16\n        let n = recvfrom(self.descriptor, buffer.data, buffer.length, 0, &raw, &length)\n        if n < 0:\n            error(failed, \"receive\")\n        return ((usize)n, Address.from_raw(raw))\n\n    pub func close():\n        discard(close(self.descriptor))\n", 7896})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"debug", 5}), .text = ((lb_str){"import c\nimport memory\n\nextern func getenv(name: c.str) -> c.str?\nextern func c_read as \"read\"(descriptor: i32, buffer: void*, count: usize) -> isize\nextern func c_exit as \"exit\"(code: i32) -> never\n\n## A frame as the compiler described it under `--debug`: the function's name and\n## source, then `count` locals laid out after it.\nextern struct Shape:\n    name: str\n    source: str\n    count: u64\n\nextern struct Local:\n    name: str\n    kind: str\n    offset: u64\n    size: u64\n\nstruct Activation:\n    var shape: Shape*?\n    var frame: void*?\n    var line: u32\n\nstruct Break:\n    var file: str\n    var line: u32\n\nvar activations: Activation[512]\nvar depth: usize\nvar checked: bool\nvar active: bool\nvar started: bool\nvar stepping: bool\nvar step_over: usize\nvar breaks: Break[32]\nvar break_count: usize\nvar names: u8[4096]\nvar names_used: usize\nvar line_bytes: u8[512]\n\n## Called at every function entry and exit of a `--debug` build.\npub func enter(shape: void*):\n    if depth < activations.length:\n        activations[depth] = Activation(shape = (Shape*)shape, frame = none, line = 0)\n    depth += 1\n\npub func leave():\n    if depth > 0:\n        depth -= 1\n\n## Called before every statement: stop when a breakpoint, a step, or the start asks.\npub func at(shape: void*, line: u32, frame: void*):\n    if not checked:\n        checked = true\n        active = getenv(\"LUCE_DEBUG\") != none\n    if not active or depth == 0 or depth > activations.length:\n        return\n    let top = depth - 1\n    let s = (Shape*)shape\n    activations[top] = Activation(shape = s, frame = frame, line = line)\n    var stop = false\n    if not started:\n        started = true\n        stop = true\n    elif stepping:\n        stop = true\n    elif step_over > 0 and depth <= step_over:\n        stop = true\n    elif hits(s.source, line):\n        stop = true\n    if not stop:\n        return\n    stepping = false\n    step_over = 0\n    print(f\"stopped at {s.source}:{line} in {s.name}\")\n    prompt(top)\n\nfunc hits(file: str, line: u32) -> bool:\n    var i: usize = 0\n    while i < break_count:\n        let b = breaks[i]\n        if b.line == line and (b.file == file or ends_with(file, b.file)):\n            return true\n        i += 1\n    return false\n\nfunc ends_with(text: str, suffix: str) -> bool:\n    if suffix.length > text.length:\n        return false\n    return (str)text.bytes[text.length - suffix.length..] == suffix\n\n## Read commands until one lets the program run.\nfunc prompt(top: usize):\n    while true:\n        let line = read_line() else return\n        let command = first_word(line)\n        let rest = trim((str)line.bytes[command.length..])\n        if command == \"r\" or command == \"run\" or command == \"c\" or command == \"continue\":\n            return\n        if command == \"s\" or command == \"step\":\n            stepping = true\n            return\n        if command == \"n\" or command == \"next\":\n            step_over = depth\n            return\n        if command == \"q\" or command == \"quit\":\n            print(\"quit\")\n            c_exit(0)\n        if command == \"b\" or command == \"break\":\n            add_break(rest)\n        elif command == \"p\" or command == \"print\":\n            show_named(top, rest)\n        elif command == \"locals\":\n            show_all(top)\n        elif command == \"bt\" or command == \"backtrace\":\n            backtrace()\n        elif command.length == 0:\n            continue\n        else:\n            print(f\"unknown command `{command}`; commands: break FILE:LINE, run, step, next, print NAME, locals, backtrace, quit\")\n\nfunc add_break(spec: str):\n    var colon: usize = spec.length\n    var i = spec.length\n    while i > 0:\n        i -= 1\n        if spec.bytes[i] == ':':\n            colon = i\n            break\n    if colon == spec.length:\n        print(\"break needs FILE:LINE\")\n        return\n    let file = (str)spec.bytes[..<colon]\n    let number = parse_line((str)spec.bytes[colon + 1..])\n    if number == 0 or break_count == breaks.length or names_used + file.length > names.length:\n        print(\"cannot set that breakpoint\")\n        return\n    memory.copy(names[names_used..], file.bytes, file.length)\n    let kept = (str)names[names_used..<names_used + file.length]\n    names_used += file.length\n    breaks[break_count] = Break(file = kept, line = number)\n    break_count += 1\n    print(f\"breakpoint {break_count} at {file}:{number}\")\n\nfunc parse_line(text: str) -> u32:\n    var value: u32 = 0\n    for byte in text.bytes:\n        if byte < '0' or byte > '9':\n            return 0\n        value = value * 10 + (u32)(byte - '0')\n    return value\n\nfunc backtrace():\n    var i = depth\n    var index: usize = 0\n    while i > 0:\n        i -= 1\n        let a = activations[i]\n        if let s = a.shape:\n            print(f\"#{index} {s.name} at {s.source}:{a.line}\")\n        index += 1\n\nfunc show_all(top: usize):\n    let a = activations[top]\n    let s = a.shape else return\n    var i: u64 = 0\n    while i < s.count:\n        show(local_of(s, i), a.frame)\n        i += 1\n\nfunc show_named(top: usize, name: str):\n    let a = activations[top]\n    let s = a.shape else return\n    var i: u64 = 0\n    while i < s.count:\n        let described = local_of(s, i)\n        if described.name == name:\n            show(described, a.frame)\n            return\n        i += 1\n    print(f\"no local named `{name}`\")\n\n## The locals follow the shape, each `sizeof(Local)` bytes.\nfunc local_of(s: Shape*, index: u64) -> Local*:\n    let base = (usize)s + sizeof(Shape) + (usize)index * sizeof(Local)\n    return (Local*)base\n\n## A local's value read from the frame and shown by its type's spelling.\nfunc show(described: Local*, frame: void*?):\n    let f = frame else return\n    let address = (void*)((usize)f - (usize)described.offset)\n    let kind = described.kind\n    if kind == \"i64\" or kind == \"isize\":\n        print(f\"{described.name}: {kind} = {memory.read[i64](address)}\")\n    elif kind == \"i32\":\n        print(f\"{described.name}: {kind} = {memory.read[i32](address)}\")\n    elif kind == \"i16\":\n        print(f\"{described.name}: {kind} = {memory.read[i16](address)}\")\n    elif kind == \"i8\":\n        print(f\"{described.name}: {kind} = {memory.read[i8](address)}\")\n    elif kind == \"u64\" or kind == \"usize\":\n        print(f\"{described.name}: {kind} = {memory.read[u64](address)}\")\n    elif kind == \"u32\" or kind == \"char\":\n        print(f\"{described.name}: {kind} = {memory.read[u32](address)}\")\n    elif kind == \"u16\":\n        print(f\"{described.name}: {kind} = {memory.read[u16](address)}\")\n    elif kind == \"u8\":\n        print(f\"{described.name}: {kind} = {memory.read[u8](address)}\")\n    elif kind == \"bool\":\n        print(f\"{described.name}: {kind} = {memory.read[bool](address)}\")\n    elif kind == \"f64\":\n        print(f\"{described.name}: {kind} = {memory.read[f64](address)}\")\n    elif kind == \"f32\":\n        print(f\"{described.name}: {kind} = {memory.read[f32](address)}\")\n    elif kind == \"str\":\n        let text = memory.read[str](address)\n        print(f\"{described.name}: {kind} = \\\"{text}\\\"\")\n    elif kind == \"c.str\":\n        let text = memory.read[c.str](address)\n        print(f\"{described.name}: {kind} = \\\"{(str)text}\\\"\")\n    elif ends_with(kind, \"*\") or ends_with(kind, \"*?\"):\n        print(f\"{described.name}: {kind} = 0x{hex(memory.read[usize](address))}\")\n    else:\n        var shown: usize = (usize)described.size\n        if shown > 32:\n            shown = 32\n        var text: u8[160]\n        var used: usize = 0\n        var i: usize = 0\n        while i < shown:\n            let byte = memory.read[u8]((void*)((usize)address + i))\n            let digits = \"0123456789abcdef\".bytes\n            text[used] = digits[(usize)(byte >> 4)]\n            text[used + 1] = digits[(usize)(byte & 15)]\n            text[used + 2] = ' '\n            used += 3\n            i += 1\n        print(f\"{described.name}: {kind} = {described.size} bytes {(str)text[..<used]}\")\n\nfunc first_word(line: str) -> str:\n    var i: usize = 0\n    while i < line.length and line.bytes[i] != ' ':\n        i += 1\n    return (str)line.bytes[..<i]\n\nfunc trim(text: str) -> str:\n    var start: usize = 0\n    var end = text.length\n    while start < end and text.bytes[start] == ' ':\n        start += 1\n    while end > start and (text.bytes[end - 1] == ' ' or text.bytes[end - 1] == '\\r'):\n        end -= 1\n    return (str)text.bytes[start..<end]\n\n## One line from standard input, without its newline; none at the end of input.\nfunc read_line() -> str?:\n    var used: usize = 0\n    while used < line_bytes.length:\n        var byte: u8[1]\n        let n = c_read(0, &byte[0], 1)\n        if n <= 0:\n            if used == 0:\n                return none\n            break\n        if byte[0] == '\\n':\n            break\n        line_bytes[used] = byte[0]\n        used += 1\n    return (str)line_bytes[..<used]\n", 8765})}), ((lb_sema_prelude_Prelude){.name = ((lb_str){"c", 1}), .text = ((lb_str){"## C's types live here (base.md \302\2475.2); the checker supplies them, since their widths are the\n## target's: `c.int` and the other fixed-width ones are Base types by another name, `c.char`,\n## `c.long`, `c.ulong`, and `c.wchar` are distinct, `c.va_list` is opaque, `c.str` is C text.\n\n## The C standard streams; the backend supplies them.\npub func stdin() -> void*:\n    trap(\"supplied by the backend\")\npub func stdout() -> void*:\n    trap(\"supplied by the backend\")\npub func stderr() -> void*:\n    trap(\"supplied by the backend\")\n", 528})})}});
